import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Dict, Any, Sequence

def _define_hyperparameters():
    # Combining hyperparameters from my SOTA and Noema I's SOTA
    return {
        'learning_rate': 0.001,
        'd_model': 256,
        'num_blocks': 5,
        'dilations': [1, 2, 4, 8, 16],
        'kernel_size': 7,
        'dropout_rate': 0.1, # Using Noema's lower dropout
        'gru_hidden_size': 128,
        'hidden_dim': 512
    }

class DSConvDilatedBlock(nn.Module):
    d_model: int
    kernel_size: int
    dilation: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,), feature_group_count=self.d_model, padding='SAME', kernel_dilation=(self.dilation,))(h)
        h = nn.gelu(h)
        h = nn.Conv(features=self.d_model, kernel_size=(1,))(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x + h

class SynergisticDualPath(nn.Module):
    d_output: int
    task_type: str
    d_model: int
    num_blocks: int
    dilations: Sequence[int]
    kernel_size: int
    dropout_rate: float
    gru_hidden_size: int
    hidden_dim: int

    @nn.compact
    def __call__(self, x, deterministic=True):
        # 1. Input Projection & SOTA Backbone
        h = nn.Dense(self.d_model)(x)
        h = nn.gelu(h)
        for i in range(self.num_blocks):
            h = DSConvDilatedBlock(d_model=self.d_model, kernel_size=self.kernel_size, dilation=self.dilations[i], dropout_rate=self.dropout_rate)(h, deterministic=deterministic)
        cnn_features = h

        # 2. Path A: Pooling (Mean + Max)
        mean_pooled = jnp.mean(cnn_features, axis=1)
        max_pooled = jnp.max(cnn_features, axis=1)
        pooled_features = jnp.concatenate([mean_pooled, max_pooled], axis=-1)

        # 3. Path B: BiGRU
        forward_hidden = nn.RNN(nn.GRUCell(features=self.gru_hidden_size), name="FwdGRU")(cnn_features)[:, -1, :]
        backward_hidden = nn.RNN(nn.GRUCell(features=self.gru_hidden_size), name="BwdGRU")(jnp.flip(cnn_features, axis=1))[:, -1, :]
        recurrent_features = jnp.concatenate([forward_hidden, backward_hidden], axis=-1)

        # 4. Concatenate both paths
        combined_features = jnp.concatenate([pooled_features, recurrent_features], axis=-1)

        # 5. Prediction Head
        z = nn.LayerNorm()(combined_features)
        z = nn.Dense(features=self.hidden_dim)(z)
        z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        logits = nn.Dense(features=self.d_output)(z)

        if self.task_type == 'regression' and self.d_output == 1:
            return logits.squeeze(-1)
        return logits

class SynergyWrapper:
    def __init__(self, **kwargs):
        self.network = SynergisticDualPath(**kwargs)

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
      if deterministic:
          return self.network.apply({'params': params}, x, deterministic=True)
      else:
          if rng_key is None: rng_key = random.PRNGKey(0)
          return self.network.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
  network_param_keys = {
      'd_output', 'task_type', 'd_model', 'num_blocks', 'dilations',
      'kernel_size', 'dropout_rate', 'gru_hidden_size', 'hidden_dim'
  }
  network_params = {k: v for k, v in hparams.items() if k in network_param_keys}
  # Ensure dilations is a tuple for hashing
  if 'dilations' in network_params:
      network_params['dilations'] = tuple(network_params['dilations'])
  return SynergyWrapper(**network_params)
